#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>
#include <format>

std::string etiqueta(const std::string& codigo, int cantidad) {
    return std::format("[{0:<6}]|[{1:04d}]|[{1:x}]", codigo, cantidad);
}

int main() {
    int cantidad = 10;
    std::cout << etiqueta("Sur", cantidad) << "\n" << etiqueta("Pasillo", 31) << "\n"
        << etiqueta("", 0) << "\n" << etiqueta("Taller", 1000) << "\n" << cantidad + 1;
    return 0;
}

